/* eslint-disable react/prop-types */
import React from 'react';
import { Box, Button, Modal, Typography } from '@mui/material';
import { useMyContext } from '../../pages/provider';
import useResponsive from '../../hooks/useResponsive';

const DeleteModal = ({ isDeleteOpen, handleClose, handleDelete }) => {
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm')

    const style1 = {
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        width: isMobile ? "90%" : 400,
        backgroundColor: 'white',
        borderRadius: '8px',
        boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
        p: isMobile ? 2 : 4,
    };

    return (
        <Modal
            open={isDeleteOpen}
            onClose={handleClose}
            aria-labelledby="modal-modal-title"
            aria-describedby="modal-modal-description"
        >
            <Box sx={style1}>
                <div className="d-flex justify-content-around">
                    <Typography id="modal-modal-title" variant="h6" component="h2">
                        {i18?.ACCOUNTSTITLE?.DELETE_PROMPT || "Are you sure you want to delete?"}
                    </Typography>
                </div>
                <div className="d-flex justify-content-around mt-3">
                    <Button variant="contained" size="medium" color="error" onClick={handleClose}>
                        {i18?.ACCOUNTSTITLE?.NO || "No"}
                    </Button>
                    <Button variant="contained" size="medium" color="primary" onClick={handleDelete}>
                        {i18?.ACCOUNTSTITLE?.YES || "Yes"}
                    </Button>
                </div>
            </Box>
        </Modal>
    );
};

export default DeleteModal;
